  public SaveEnvironments(Engine e){if(e==null)throw new ArgumentNullException("e");engine=e;sourceGame=Full(e.Game);user=Full(e.User);data=Full(e.Data);store=System.IO.Path.Combine(data,"save-environments");index=System.IO.Path.Combine(store,"index.json");Safe(data);}
  SaveEnvironments(string dataRoot){data=Full(dataRoot);store=System.IO.Path.Combine(data,"save-environments");index=System.IO.Path.Combine(store,"index.json");Safe(data);}
  // Engine clones and background workers resolve registered ownership without
  // constructing another Engine or consulting any mutable source installation.
  internal static SaveEnvironmentRecord FindOwned(string dataRoot,string gamePath,string userPath){
   string game=Full(gamePath),selectedUser=Full(userPath);var reader=new SaveEnvironments(dataRoot);
   return reader.Locked(()=>{var catalog=reader.Load();var matches=catalog.Document.Records.Where(row=>Same(System.IO.Path.Combine(row.RootPath,"game"),game)&&Same(row.UserPath,selectedUser)).ToArray();if(matches.Length==0)return null;if(matches.Length!=1)throw new IOException("快照游戏与用户身份存在重复登记。");return reader.ReadRecord(matches[0],catalog.Stamp);});
  }
  internal static bool OwnsUser(string dataRoot,string gamePath,string userPath){try{return FindOwned(dataRoot,gamePath,userPath)!=null;}catch{return false;}}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=MaxManifest,RecursionLimit=32};}
  static string Full(string path){return VersionLibrary.Full(path);}
  static string Absolute(string path){if(!System.IO.Path.IsPathRooted(path??""))throw new IOException("Java 目录不是明确的绝对路径。");return Full(path);}
  static bool Same(string a,string b){return string.Equals(Full(a),Full(b),StringComparison.OrdinalIgnoreCase);}
  static bool Within(string child,string parent){return VersionLibrary.Within(child,parent);}
  static void Safe(string path){LauncherMaintenance.NoReparse(Full(path));}
  static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes??new byte[0])).Replace("-","").ToLowerInvariant();}
  static bool Opaque(string value){return Regex.IsMatch(value??"",@"\A[a-f0-9]{32}\z");}
  static bool Digest(string value){return Regex.IsMatch(value??"",@"\A[a-f0-9]{64}\z");}
  static byte[] Read(string path,int maximum){Safe(path);if(!File.Exists(path))return null;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(stream.Length>maximum)throw new IOException("快照元数据超过安全读取上限。");byte[] bytes=new byte[(int)stream.Length];int offset=0,count;while(offset<bytes.Length&&(count=stream.Read(bytes,offset,bytes.Length-offset))>0)offset+=count;if(offset!=bytes.Length)throw new IOException("快照文件在读取期间改变。");return bytes;}}
  static string[] Strings(object value){if(value==null)return new string[0];if(value is string||!(value is IEnumerable))throw new IOException("快照模组清单无效。");return ((IEnumerable)value).Cast<object>().Select(item=>{if(!(item is string))throw new IOException("快照模组标识无效。");return (string)item;}).ToArray();}
  static string Canonical(string id){return id.TrimStart('\\');}
  static void SaveId(string id){if(!SaveDeletion.ValidId(id)||id.Split('/')[0].Equals("Multiplayer",StringComparison.OrdinalIgnoreCase))throw new IOException("请选择有效的单人存档。");}
  string Binding(string id){SaveId(id);return Hash(Utf8.GetBytes(sourceGame.ToUpperInvariant()+"\n"+user.ToUpperInvariant()+"\n"+id));}
  T Locked<T>(Func<T> work){using(var mutex=new Mutex(false,"Local\\OrangeSaveEnvironments-"+Hash(Utf8.GetBytes(data.ToUpperInvariant())))){bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("另一个游戏与模组快照任务正在发布，请稍后重试。");return work();}finally{if(held)mutex.ReleaseMutex();}}}
  Index Load(){
   byte[] bytes=Read(index,MaxIndex);Document doc;
   try{doc=bytes==null?new Document():Json().Deserialize<Document>(Utf8.GetString(bytes));}catch(Exception error){throw new IOException("快照目录记录损坏，原文件已保留。",error);}
   if(doc==null||doc.Schema!=1||doc.Records==null||doc.Records.Count>MaxRecords||doc.Bindings==null||doc.Bindings.Count>MaxRecords*2)throw new IOException("快照目录格式无效。");
   var ids=new HashSet<string>(StringComparer.Ordinal);var roots=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   foreach(var row in doc.Records){if(row==null||!Opaque(row.Id)||!ids.Add(row.Id)||!Digest(row.ManifestHash)||!System.IO.Path.IsPathRooted(row.RootPath??"")||!roots.Add(Full(row.RootPath))||!System.IO.Path.IsPathRooted(row.SourceGame??"")||!System.IO.Path.IsPathRooted(row.UserPath??"")||!SaveDeletion.ValidId(row.SaveId))throw new IOException("快照目录包含无效身份。");}
   if(doc.Bindings.Any(pair=>!Digest(pair.Key)||!ids.Contains(pair.Value)))throw new IOException("快照绑定记录无效。");
