  }
  static bool EqualBytes(byte[] a,byte[] b){return a==null?b==null:b!=null&&a.SequenceEqual(b);}
  void Persist(Index before){
   Safe(store);Directory.CreateDirectory(store);if(!EqualBytes(Read(index,MaxIndex),before.Bytes))throw new IOException("快照目录已被其他程序修改，请刷新。");before.Document.Revision=Guid.NewGuid().ToString("N");byte[] bytes=Utf8.GetBytes(Json().Serialize(before.Document));if(bytes.Length>MaxIndex)throw new IOException("快照目录记录过大。");string temporary=index+".new-"+Guid.NewGuid().ToString("N");
   try{using(var output=new FileStream(temporary,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}if(!EqualBytes(Read(index,MaxIndex),before.Bytes))throw new IOException("快照目录在发布期间变化。");if(File.Exists(index))File.Replace(temporary,index,null);else File.Move(temporary,index);}finally{if(File.Exists(temporary))File.Delete(temporary);}
  }
  void Context(){if(!Same(engine.Game,sourceGame)||!Same(engine.User,user)||!Same(engine.Data,data))throw new IOException("所选游戏或用户目录已变化，请刷新。");if(Within(user,sourceGame)||Within(sourceGame,user))throw new IOException("游戏与用户目录不能交叉；请使用独立的用户目录后创建快照，避免复制原存档。");Safe(user);Safe(data);}
  void Stopped(){Context();Safe(sourceGame);if(!engine.TestMode&&engine.RuntimeRunning())throw new IOException("请先退出游戏，再创建或切换快照。");if(LaunchProfiles.Pending(engine)||PlayProfileTransaction.Pending(engine)||BuddyTakeover.Pending(engine))throw new IOException("请先完成当前启动或配置恢复任务。");}
  void RequireBoundIdle(Index catalog,string saveId){string id;if(!catalog.Document.Bindings.TryGetValue(Binding(saveId),out id))return;var pointer=catalog.Document.Records.Single(row=>row.Id==id);if(!Belongs(pointer)||pointer.SaveId!=saveId)throw new IOException("快照绑定与当前存档不一致。");string game=System.IO.Path.Combine(pointer.RootPath,"game"),token=DlssInstaller.Hash(Utf8.GetBytes(System.IO.Path.GetFullPath(game).ToUpperInvariant()+"|"+System.IO.Path.GetFullPath(user).ToUpperInvariant())),journal=System.IO.Path.Combine(data,"launch-sessions",token+".json");Safe(journal);if(File.Exists(journal))throw new IOException("此存档的快照启动会话尚未结束，请先完成恢复。");if(!engine.TestMode&&GameProcessGuard.IsClientRunning(game,engine.ProcessInventory))throw new IOException("此存档的快照游戏仍在运行，请先退出游戏。");}
  static string Child(string root,string relative){Relative(relative);string path=Full(System.IO.Path.Combine(root,relative.Replace('/',System.IO.Path.DirectorySeparatorChar)));if(!Within(path,root)||Same(path,root))throw new IOException("快照文件路径越界。");return path;}
  static void Relative(string path){if(string.IsNullOrWhiteSpace(path)||path.Length>2000||path.IndexOf('\\')>=0||path.Split('/').Any(part=>part==""||part=="."||part==".."||part.EndsWith(".",StringComparison.Ordinal)||part.EndsWith(" ",StringComparison.Ordinal)||part.IndexOfAny(System.IO.Path.GetInvalidFileNameChars())>=0))throw new IOException("快照包含无效的相对文件名。");}
  static string FileHash(string path,CancellationToken token){Safe(path);using(var sha=SHA256.Create())using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){byte[] buffer=new byte[1048576];int count;while((count=input.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();sha.TransformBlock(buffer,0,count,null,0);}sha.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(sha.Hash).Replace("-","").ToLowerInvariant();}}
  static SaveEnvironmentFile[] Scan(string root,bool hashes,CancellationToken token,Func<string,bool> exclude=null){
   Safe(root);if(!Directory.Exists(root))throw new IOException("快照来源目录已不存在。");var files=new List<SaveEnvironmentFile>();var pending=new Stack<string>();pending.Push(root);
   while(pending.Count>0){string directory=pending.Pop();Safe(directory);foreach(string path in Directory.EnumerateFileSystemEntries(directory)){token.ThrowIfCancellationRequested();Safe(path);string relative=path.Substring(root.Length+1).Replace('\\','/');Relative(relative);if(exclude!=null&&exclude(relative))continue;bool isDirectory=(File.GetAttributes(path)&FileAttributes.Directory)!=0;var entry=new SaveEnvironmentFile{Path=relative,Directory=isDirectory};if(isDirectory)pending.Push(path);else{var info=new FileInfo(path);entry.Bytes=info.Length;entry.WriteTicks=info.LastWriteTimeUtc.Ticks;if(hashes)entry.Hash=FileHash(path,token);}files.Add(entry);if(files.Count>MaxFiles)throw new IOException("快照文件数量超过安全上限。");}}
   return files.OrderBy(item=>item.Path,StringComparer.OrdinalIgnoreCase).ToArray();
  }
  static bool Match(SaveEnvironmentFile[] a,SaveEnvironmentFile[] b,bool hashes){return a.Length==b.Length&&a.Zip(b,(x,y)=>x.Path==y.Path&&x.Directory==y.Directory&&x.Bytes==y.Bytes&&x.WriteTicks==y.WriteTicks&&(!hashes||x.Hash==y.Hash)).All(value=>value);}
  static bool SameContent(SaveEnvironmentFile[] a,SaveEnvironmentFile[] b){return a.Length==b.Length&&a.Zip(b,(x,y)=>x.Path==y.Path&&x.Directory==y.Directory&&x.Bytes==y.Bytes&&x.Hash==y.Hash).All(value=>value);}
  static void VerifyCopiedMods(SaveEnvironmentRecord record){foreach(var mapping in record.ModRoots){string prefix=mapping.CopiedRoot.Substring(record.RootPath.Length+1).Replace('\\','/')+"/";var copied=record.Files.Where(file=>file.Path.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)).Select(file=>new SaveEnvironmentFile{Path=file.Path.Substring(prefix.Length),Hash=file.Hash,Bytes=file.Bytes,Directory=file.Directory}).ToArray();if(!SameContent(mapping.SourceFiles,copied))throw new IOException("运行环境准备改变了已复制的模组内容，未启用新快照。");}}
  static long Size(IEnumerable<SaveEnvironmentFile> files){return files.Where(item=>!item.Directory).Sum(item=>item.Bytes);}
  static string[] Arguments(Dictionary<string,object> config){object value;if(!config.TryGetValue("vmArgs",out value))return new string[0];return Strings(value);}
  static IEnumerable<Dictionary<string,object>> Branches(Dictionary<string,object> config){foreach(var value in config.Values.OfType<Dictionary<string,object>>()){if(value.ContainsKey("vmArgs"))yield return value;foreach(var nested in Branches(value))yield return nested;}}
  internal static SaveEnvironmentBuddyConfiguration BuddyConfiguration(Engine e){
   var result=new SaveEnvironmentBuddyConfiguration();byte[] launch=Read(e.Config,2097152);if(launch==null)throw new IOException("游戏启动配置不存在。");var root=Json().Deserialize<Dictionary<string,object>>(Utf8.GetString(launch));if(root==null)throw new IOException("游戏启动配置无效。");string[] basic=Arguments(root);var choices=new List<string[]>{basic};choices.AddRange(Branches(root).Select(branch=>basic.Concat(Arguments(branch)).ToArray()));var directories=new HashSet<string>(StringComparer.OrdinalIgnoreCase);bool? enabled=null;
   foreach(string[] args in choices){string home=null,directory=null;int agents=0;foreach(string arg in args){if(arg.StartsWith("-Duser.home=",StringComparison.Ordinal)){string found=Absolute(arg.Substring(12));if(home!=null&&!Same(home,found))throw new IOException("不同 Java 用户目录覆盖冲突。");home=found;}if(arg.StartsWith("-D",StringComparison.Ordinal)&&arg.IndexOf("config_dir",StringComparison.OrdinalIgnoreCase)>=0)throw new IOException("Buddy 系统属性目录覆盖无法核实。");
     string options=null;if(arg.StartsWith("-agentlib:zbNative",StringComparison.Ordinal)){string rest=arg.Substring(18);if(rest!=""&&!rest.StartsWith("=",StringComparison.Ordinal))throw new IOException("Buddy 启动代理无法核实。");options=rest.TrimStart('=');}else if(arg.StartsWith("-javaagent:",StringComparison.Ordinal)){string tail=arg.Substring(11);int at=tail.IndexOf('=');string file=at<0?tail:tail.Substring(0,at);if(System.IO.Path.GetFileName(file).Equals("ZombieBuddy.jar",StringComparison.OrdinalIgnoreCase)){string resolved=System.IO.Path.IsPathRooted(file)?Full(file):Full(System.IO.Path.Combine(e.Game,file));if(!Same(resolved,System.IO.Path.Combine(e.Game,"ZombieBuddy.jar")))throw new IOException("Buddy 代理位于游戏目录外，无法完整复制。");options=at<0?"":tail.Substring(at+1);}else if(!GameStartupComponent.IsOwnedArgument(e,arg)&&!GameStartupComponent.CanPrepareOwnedArgument(e,arg))throw new IOException("存在未归属的独立 Java 代理，无法创建完整快照。");}else if(arg.StartsWith("-agentpath:",StringComparison.Ordinal)||arg.StartsWith("-agentlib:",StringComparison.Ordinal))throw new IOException("存在无法完整核实的原生启动代理。");
     if(options==null)continue;agents++;foreach(string option in options.Split(',')){if(option=="")continue;string[] pair=option.Split(new[]{'='},2);if(pair[0]!="config_dir"||pair.Length!=2)throw new IOException("Buddy 自定义启动选项无法完整核实。");string found=Absolute(pair[1]);if(directory!=null&&!Same(directory,found))throw new IOException("Buddy 配置目录覆盖冲突。");directory=found;}}
    if(agents>1||enabled.HasValue&&enabled.Value!=(agents==1))throw new IOException("不同启动分支的 Buddy 代理不一致。");enabled=agents==1;if(agents==1)directories.Add(directory??System.IO.Path.Combine(home??Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".zombie_buddy"));
   }
   result.Enabled=enabled==true;if(!result.Enabled)return result;foreach(string key in new[]{"JAVA_TOOL_OPTIONS","_JAVA_OPTIONS","JDK_JAVA_OPTIONS"})if(!string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(key)))throw new IOException("Java 环境变量存在额外启动参数，无法冻结完整加载环境。");if(directories.Count!=1)throw new IOException("不同启动分支的 Buddy 配置目录不一致。");result.Directory=Full(directories.Single());result.ConfigPath=System.IO.Path.Combine(result.Directory,"config.json");result.ApprovalsPath=System.IO.Path.Combine(result.Directory,"mod_approvals.json");result.ConfigBytes=Read(result.ConfigPath,2097152);result.ApprovalBytes=Read(result.ApprovalsPath,2097152);
   if(result.ConfigBytes!=null){var config=Json().Deserialize<Dictionary<string,object>>(Utf8.GetString(result.ConfigBytes));object raw;if(config==null)throw new IOException("Buddy 配置无法读取。");if(config.TryGetValue("preload_mods",out raw)){var preloads=raw as Dictionary<string,object>;if(preloads==null||preloads.Count>2000)throw new IOException("Buddy 预加载清单无效。");foreach(var pair in preloads){string id=Canonical(pair.Key);if(!SaveProfiles.Id(id)||result.PreloadInfo.ContainsKey(id))throw new IOException("Buddy 预加载标识无效或重复。");var item=pair.Value as Dictionary<string,object>;object info,jar;if(item==null||!item.TryGetValue("infPath",out info)||!(info is string)||!item.TryGetValue("jarPath",out jar)||!(jar is string)||!System.IO.Path.IsPathRooted((string)info)||!System.IO.Path.IsPathRooted((string)jar))throw new IOException("Buddy 预加载来源不完整。");result.PreloadInfo.Add(id,Full((string)info));result.PreloadJars.Add(id,Full((string)jar));}result.PreloadModIds=result.PreloadInfo.Keys.ToArray();}}
