  Capture CaptureSources(string saveId,Index catalog,CancellationToken token){
   token.ThrowIfCancellationRequested();Context();SaveId(saveId);string save=SaveProfiles.ResolveSave(engine,saveId);if(!GameDiscovery.IsGameFolder(sourceGame))throw new IOException("当前游戏安装不完整。");var version=LauncherStatusMetadata.GameVersion(sourceGame);if(version.state!="known")throw new IOException("无法确认当前游戏版本，请先核对安装。");Version number;if(!Version.TryParse(version.value,out number)||(number.Major!=41&&number.Major!=42))throw new IOException("当前快照仅支持已核实的 B41 或 B42 游戏。");
