   string[] selected=capture.Mods.Concat(capture.Defaults).Concat(capture.Buddy.PreloadModIds).Distinct(StringComparer.Ordinal).ToArray();if(selected.Length>2000)throw new IOException("启用模组数量超过快照安全上限。");ModConfigurations.ValidatePreflightMods(selected);var warnings=new List<string>();var budget=new LaunchReadBudget(67108864,100000);budget.Capture();var entries=SaveProfiles.SnapshotEntries(engine,selected,warnings,budget);if(budget.Incomplete)throw new IOException("模组来源扫描不完整，未创建部分快照。");
   var selectedIds=new HashSet<string>(selected.Select(Canonical),StringComparer.Ordinal);foreach(string id in selected){var matches=entries.Candidates.Where(row=>row.Id==Canonical(id)).ToArray();if(matches.Length!=1)throw new IOException(matches.Length==0?"模组来源缺失："+id:"模组存在多个来源，无法冻结："+id);var entry=entries.Entries.Where(row=>row.id==Canonical(id)).ToArray();if(entry.Length!=1)throw new IOException("模组元数据无法唯一确定："+id);foreach(string dependency in entry[0].requires)if(!selectedIds.Contains(Canonical(dependency)))throw new IOException("启用模组缺少依赖："+id+" → "+dependency);}
   var ordered=ModConfigurations.SortSavedPreflight(engine,capture.Mods,entries,warnings);if(ordered.errors.Length>0||ordered.violations.Length>0)throw new IOException(string.Join("\n",ordered.errors.Concat(ordered.violations)));
   var candidates=selected.Select(id=>entries.Candidates.Single(row=>row.Id==Canonical(id))).GroupBy(row=>Full(row.Root),StringComparer.OrdinalIgnoreCase).ToArray();capture.Sources=candidates.Select(group=>new Source{Candidate=group.First(),Ids=selected.Where(id=>Same(entries.Candidates.Single(row=>row.Id==Canonical(id)).Root,group.Key)).ToArray(),Files=Scan(group.Key,false,token)}).ToArray();
   foreach(string id in capture.Buddy.PreloadModIds){var candidate=entries.Candidates.Single(row=>row.Id==id);string info=capture.Buddy.PreloadInfo[id],jar=capture.Buddy.PreloadJars[id];if(!Within(info,candidate.Root)||!Within(jar,candidate.Root)||!File.Exists(info)||!File.Exists(jar))throw new IOException("Java 预加载来源不属于已复制的模组："+id);}
   capture.Game=Scan(sourceGame,false,token,relative=>Mutable("game/"+relative));budget.Evidence.Validate();capture.Plan=new SaveEnvironmentPlan{saveId=saveId,gameVersion=version.value,gameBytes=Size(capture.Game),modBytes=capture.Sources.Sum(row=>Size(row.Files)),modCount=selectedIds.Count,warnings=warnings.Distinct().Take(100).ToArray(),ready=true,bindingStamp=catalog.Stamp};
   capture.Plan.stamp=Hash(Utf8.GetBytes(Json().Serialize(new{binding=catalog.Stamp,game=sourceGame,user=user,save=saveId,saveStamp=capture.SaveStamp,version=version.value,gameFiles=capture.Game,mods=capture.Sources.Select(row=>new{root=row.Candidate.Root,ids=row.Ids,files=row.Files}).ToArray(),buddy=Hash(capture.Buddy.ConfigBytes),approvals=Hash(capture.Buddy.ApprovalBytes)})));return capture;
  }
  public SaveEnvironmentPlan Preview(string saveId){return Preview(saveId,CancellationToken.None);}
