  // Process polling needs only indexed paths; never deserialize historical payload manifests here.
  internal string[] ProcessGames(){return Locked(()=>Load().Document.Records.Where(Belongs).Select(row=>Full(System.IO.Path.Combine(row.RootPath,"game"))).Distinct(StringComparer.OrdinalIgnoreCase).ToArray());}
